#include <stddef.h>
void sha256(const void*a,size_t b,uint8_t*c){(void)a;(void)b;(void)c;}
void sha384(const void*a,size_t b,uint8_t*c){(void)a;(void)b;(void)c;}
void sha512(const void*a,size_t b,uint8_t*c){(void)a;(void)b;(void)c;}
int rsa_modexp_be(const uint8_t*,int,const uint8_t*,int,const uint8_t*,int,uint8_t*);
static int hexb(const char*h,uint8_t*o){int n=0;while(h[2*n]){int v;sscanf(h+2*n,"%2x",&v);o[n]=(uint8_t)v;n++;}return n;}
static int fails;
static void chk(const char*name,const char*nh,const char*eh,const char*bh,const char*wh){
  uint8_t N[600],E[8],B[600],W[600],O[600];
  int nl=hexb(nh,N),el=hexb(eh,E),bl=hexb(bh,B),wl=hexb(wh,W);
  int rc=rsa_modexp_be(B,bl,E,el,N,nl,O);
  if(rc!=0){printf("FAIL %s rc=%d\n",name,rc);fails++;return;}
  if(wl!=nl||memcmp(O,W,nl)){printf("FAIL %s mismatch\n",name);fails++;return;}
  printf("ok   %s (%d-bit)\n",name,nl*8);
}
